function repairJson(raw) {
  var s=raw.indexOf("{"),e=raw.lastIndexOf("}");
  if(s===-1||e===-1) throw new Error("No JSON found in response.");
  var str=raw.slice(s,e+1);

  // Walk the JSON char by char. When inside a string value, collect
  // all characters until we hit a quote that is genuinely the closing
  // quote — identified as: not escaped AND the JSON structure character
  // that follows (after optional whitespace) is one of  : , } ]
  // Any other quote inside a string gets dropped.
  // Also sanitise control chars, smart quotes, and apostrophes.
  var out = "";
  var i = 0, len = str.length;

  function peek(offset) { return str[i + (offset||1)] || ""; }
  function isStructural(ch) { return ch===":"||ch===","||ch==="}"||ch==="]"; }
  function nextNonSpace(from) {
    var k = from;
    while(k < len && (str[k]===" "||str[k]==="\t"||str[k]==="\r"||str[k]==="\n")) k++;
    return str[k]||"";
  }

  while(i < len) {
    var c = str[i], code = str.charCodeAt(i);

    // Outside a string: copy structural characters as-is
    if(c === '"') {
      // Start of a string value — collect until real closing quote
      out += '"';
      i++;
      var strContent = "";
      while(i < len) {
        var sc = str[i], scode = str.charCodeAt(i);
        if(sc === "\\") {
          // Escaped character — keep both chars
          strContent += sc;
          i++;
          if(i < len){ strContent += str[i]; i++; }
          continue;
        }
        if(sc === '"') {
          // Is this the real closing quote?
          // Check what comes after it (skip whitespace)
          var nxt = nextNonSpace(i+1);
          if(isStructural(nxt) || i+1>=len) {
            // Real closing quote
            break;
          } else {
            // Unescaped quote inside value — drop it
            i++;
            continue;
          }
        }
        // Sanitise problem characters inside string values
        if(scode < 32){strContent+=" ";i++;continue;}
        if(sc==="'"){strContent+=" ";i++;continue;}
        if(scode===0x2018||scode===0x2019){strContent+=" ";i++;continue;}
        if(scode===0x201C||scode===0x201D){strContent+=" ";i++;continue;}
        if(scode===0x2013||scode===0x2014){strContent+="-";i++;continue;}
        strContent += sc;
        i++;
      }
      out += strContent + '"';
      i++; // skip closing quote
      continue;
    }

    out += c;
    i++;
  }

  try { return JSON.parse(out); }
  catch(err) {
    var pos = parseInt((err.message.match(/position (\d+)/)||[])[1]||"0");
    throw new Error("Parse failed near: "+out.slice(Math.max(0,pos-40),pos+40));
  }
}

