// ── HAVERSINE PROXIMITY LOOKUP ────────────────────────────────
function haversineMiles(lat1, lng1, lat2, lng2) {
  var R = 3958.8;
  var dLat = (lat2-lat1)*Math.PI/180;
  var dLng = (lng2-lng1)*Math.PI/180;
  var a = Math.sin(dLat/2)*Math.sin(dLat/2) +
          Math.cos(lat1*Math.PI/180)*Math.cos(lat2*Math.PI/180)*
          Math.sin(dLng/2)*Math.sin(dLng/2);
  return R*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));
}

// Geocode a city string to {lat,lng} using the embedded table.
// Tries exact match, then state-stripped match, then partial match.
function geocodeCity(cityStr) {
  if(!cityStr) return null;
  var s = cityStr.trim();
  if(CITY_COORDS[s]) { var c=CITY_COORDS[s]; return {lat:c[0],lng:c[1]}; }
  // Try without state suffix
  var bare = s.replace(/,\s*[A-Z]{2}$/, "").trim();
  for(var key in CITY_COORDS) {
    if(key.replace(/,\s*[A-Z]{2}$/,"").trim().toLowerCase()===bare.toLowerCase()) {
      var c2=CITY_COORDS[key]; return {lat:c2[0],lng:c2[1]};
    }
  }
  return null;
}

// Find nearest campgrounds to a city string.
// prefs: {budget, rating, pets, rvLen, hookup, amenity}
// Returns array of campground option objects ready for the UI.
function findCampsNear(cityStr, prefs, maxResults) {
  maxResults = maxResults||3;
  var geo = geocodeCity(cityStr);
  if(!geo) return [];

  var maxBudget  = prefs&&prefs.budget  ? parseInt(prefs.budget)    : 9999;
  var minRating  = prefs&&prefs.rating  ? parseFloat(prefs.rating)  : 0;
  var needPets   = prefs&&prefs.pets    && prefs.pets!=="No";
  var rvLen      = prefs&&prefs.rvLen   ? parseInt(prefs.rvLen)     : 0;
  var hookupPref = prefs&&prefs.hookup  ? prefs.hookup.toLowerCase(): "";

  var scored = CAMPGROUNDS.map(function(c) {
    return {c:c, d:haversineMiles(geo.lat,geo.lng,c.lat,c.lng)};
  }).filter(function(x){ return x.d<=70; }) // 70-mile search radius
    .sort(function(a,b){ return a.d-b.d; });

  // Strict: all filters
  var strict = scored.filter(function(x){
    var c=x.c;
    if(needPets && !c.pets)               return false;
    if(c.price_low > maxBudget)           return false;
    if(c.rating < minRating)              return false;
    if(rvLen>0 && c.max_rv_ft<rvLen)      return false;
    if(hookupPref && hookupPref!=="no preference" &&
       c.hookups.toLowerCase().indexOf("full")<0 &&
       hookupPref.indexOf("full")>=0)     return false;
    return true;
  });

  // Fall back to proximity if strict is thin
  var missed = strict.length < maxResults;
  var pool   = missed ? scored : strict;

  return pool.slice(0, maxResults).map(function(x){
    var c=x.c;
    return {
      name:            c.name,
      city:            c.city,
      address:         c.address,
      phone:           c.phone,
      website:         "",
      price:           "$"+c.price_low+"-$"+c.price_high+"/night",
      priceNum:        c.price_low,
      rating:          c.rating,
      hookups:         c.hookups,
      amenities:       c.amenities.join(" "),
      pets:            c.pets,
      maxRV:           c.max_rv_ft+"ft",
      distanceMiles:   Math.round(x.d),
      distanceMinutes: Math.round(x.d*1.5), // ~40mph avg on local roads
      bestAvailable:   missed,
      missedFilters:   missed?"No exact match within 70 mi — showing nearest":"",
      tip:             c.amenities.slice(0,3).join(", ")+". "+c.hookups+"."
    };
  });
}


function loadSaved() {
  try { var s=localStorage.getItem(SAVE_KEY); return s?JSON.parse(s):null; } catch(e){return null;}
}
function saveState(state) {
  try { localStorage.setItem(SAVE_KEY, JSON.stringify(state)); } catch(e){}
}
function clearSaved() {
  try { localStorage.removeItem(SAVE_KEY); } catch(e){}
}


// ── STEP PROGRESS BAR ────────────────────────────────────────
var STEPS = [
  { num:1, icon:"📍", label:"Your Route"           },
  { num:2, icon:"🕐", label:"Driving & Rest Stops" },
  { num:3, icon:"🚐", label:"RV & Campsite Needs"  },
];

function StepBar(props) {
  var formStep = props.formStep;
  var setFormStep = props.setFormStep;
  return (
    <div style={{background:"white",borderBottom:"3px solid "+mist,padding:"20px 24px"}}>
      <div style={{maxWidth:680,margin:"0 auto",display:"flex",alignItems:"flex-start",gap:0}}>
        {STEPS.map(function(step, idx) {
          var done = formStep > step.num;
          var active = formStep === step.num;
          return (
            <div key={step.num} style={{display:"flex",alignItems:"flex-start",flex:1}}>
              <div
                onClick={done ? function(){setFormStep(step.num);} : undefined}
                style={{display:"flex",flexDirection:"column",alignItems:"center",gap:6,cursor:done?"pointer":"default",flex:1}}
              >
                <div style={{
                  width:52,height:52,borderRadius:"50%",
                  background:active?pine:done?"#6B8F6B":"#C8C8C8",
                  color:"white",display:"flex",alignItems:"center",justifyContent:"center",
                  fontSize:22,fontWeight:700,fontFamily:FONT,
                  boxShadow:active?"0 3px 12px rgba(45,74,53,0.45)":"none",
                  transition:"all 0.2s",flexShrink:0
                }}>
                  {done ? "✓" : step.num}
                </div>
                <div style={{
                  fontSize:16,fontWeight:active?700:400,
                  color:active?pine:done?"#6B8F6B":"#999",
                  textAlign:"center",fontFamily:FONT,lineHeight:1.3,
                  maxWidth:90
                }}>
                  {step.icon} {step.label}
                </div>
              </div>
              {idx < STEPS.length-1 ? (
                <div style={{
                  height:3,flex:1,marginTop:24,flexShrink:0,
                  background:done?"#6B8F6B":"#D0D0D0",
                  borderRadius:2,maxWidth:60
                }}/>
              ) : null}
            </div>
          );
        })}
      </div>
    </div>
  );
}


